// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }

    // The fuzzed parameter is the `from` address; we also fuzz a uint and decimals though they don't matter
    function testFuzz_property(address from, uint256 v, uint256 _decimals) public {
        // Keep decimals bounded to avoid overflow in exponentiation in the implementation
        _decimals = bound(_decimals, 0, 18);
        // Use an empty recipients array to trigger the require in the reference contract
        address[] memory tos = new address[](0);

        // Try the call and record whether it succeeds or reverts
        bool ok;
        try c.transfer(from, address(0x1), tos, v, _decimals) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: reference contract REVERTS for empty _tos; thus ok MUST be false for the correct contract.
        // The mutant changes require(_tos.length > 0) to >= 0, which will make ok == true for some inputs
        // (specifically when empty _tos is passed). So assert that the call reverted (ok == false).
        assertTrue(!ok);
    }
}
